import json

with open('/data/fees.json') as f:
    fees = json.load(f)

schemes = ['GlobalCard', 'NexPay', 'SwiftCharge', 'TransactPlus']
for s in schemes:
    s_rules = [r for r in fees if r['card_scheme'] == s]
    acis = set()
    all_acis = False
    for r in s_rules:
        if r['aci'] is None:
            all_acis = True
        else:
            for a in r['aci']: acis.add(a)
    print(f"{s}: {acis if not all_acis else 'ALL'}")

